use super::*;

/// The byte span of every top-level `import_statement` in `code`, paired with the specs it encodes, in
/// DOCUMENT order. The span is exactly the statement text tree-sitter sees — no trailing newline.
/// Companion to [`import_statements`]: that returns the text (for analysis), this the positions (for
/// the in-place rewrite [`normalize_code`] does).
pub(crate) fn import_spans(code: &str) -> Vec<(usize, usize, Vec<ImportSpec>)> {
    let mut parser = Parser::new();
    if parser
        .set_language(&tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into())
        .is_err()
    {
        return Vec::new();
    }
    let Some(tree) = parser.parse(code, None) else {
        return Vec::new();
    };
    let bytes = code.as_bytes();
    let mut hits: Vec<(usize, usize, Vec<ImportSpec>)> = Vec::new();
    let mut stack = vec![tree.root_node()];
    while let Some(node) = stack.pop() {
        if node.kind() == "import_statement" {
            if let Ok(text) = node.utf8_text(bytes) {
                hits.push((node.start_byte(), node.end_byte(), parse_statement(text)));
            }
            continue;
        }
        for i in (0..node.child_count() as u32).rev() {
            if let Some(child) = node.child(i) {
                stack.push(child);
            }
        }
    }
    hits.sort_by_key(|(s, _, _)| *s);
    hits
}
